{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_counts_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None)]) == 0.5
    assert monitor_flag_rate([event("b", 1, None), event("c", 1, False)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [event("a", 0, True)],
        "large": [event("b", 0, False), event("c", 0, None), event("d", 0, False)],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 4), (2, 7), (3, 9), (10, 9)])
def test_flags_in_window(days, expected):
    assert flags_in_window([2, 3, 4], days) == expected
    assert flags_in_window([], days) == 0


def test_parse_log_values_whitespace_and_skipped_lines():
    assert parse_transcript_log([
        "\n", "  # comment,with,commas\n", "  a , -2 , 1  \n",
        "b, 0, 0", " c , 5 ,   ", "  ",
    ]) == [event("a", -2, True), event("b", 0, False), event("c", 5, None)]


@pytest.mark.parametrize("line", ["a,1", "a,1,1,extra", "a,nope,1", "a,1,yes"])
def test_parse_log_errors_report_original_line_number(line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_transcript_log(["  # ignored", "  ", line])


def test_dedupe_keeps_last_id_and_sorts_by_day_then_id():
    first = event("x", 9, True)
    last = event("x", 1, None)
    events = [first, event("z", 1, True), event("b", 2, False), last, event("a", 1, False)]
    assert dedupe_transcripts(events) == [events[4], last, events[1], events[2]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_range_and_gaps():
    events = [event("a", 0, True), event("b", 1, True), event("c", 1, True),
              event("d", 2, False), event("e", 3, None), event("f", 4, True)]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]
    assert daily_flag_counts(events, 4, 3) == []


def test_monitor_summary_pooled_rounded_with_calendar_day_window():
    groups = {
        "a": [event("a", 1, True)],
        "b": [event("b", 4, True), event("c", 4, False), event("d", 5, False),
              event("e", 5, None), event("f", 5, False)],
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.333, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 1)["recent"] == 0
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 10) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 1) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [event("z", 1, True)], "empty": [], "a": [event("a", 1, True)],
              "b": [event("b", 1, None)]}
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 9) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_sorted_and_empty_is_none():
    groups = {"z": [], "b": [event("b", 1, None)], "a": [event("a", 1, True)]}
    rates = flag_rate_by_group(groups)
    assert list(rates) == ["a", "b", "z"]
    assert rates == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_flag_streak_resets_on_zero_and_negative_values():
    assert longest_flag_streak([1, 1, 0, 1, -1, 2, 3, 4, 0, 1]) == 3
    assert longest_flag_streak([0, -1]) == 0
    assert longest_flag_streak([]) == 0
